internal class FfiException: UniffiException {
    FfiException() : base() {}
    FfiException(String @Message) : base(@Message) {}

    // Each variant is a nested class
    
    
    public class Crypto : FfiException {
        // Members
        public string @msg;

        // Constructor
        public Crypto(
                string @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class Session : FfiException {
        // Members
        public string @msg;

        // Constructor
        public Session(
                string @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class KeyChanged : FfiException {
        // Members
        public string @msg;

        // Constructor
        public KeyChanged(
                string @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    
    
    public class Internal : FfiException {
        // Members
        public string @msg;

        // Constructor
        public Internal(
                string @msg) : base(
                "@msg" + "=" + @msg) {

            this.@msg = @msg;
        }
    }
    

    
}

class FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException>, CallStatusErrorHandler<FfiException> {
    public static FfiConverterTypeFfiError INSTANCE = new FfiConverterTypeFfiError();

    public override FfiException Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new FfiException.Crypto(
                    FfiConverterString.INSTANCE.Read(stream));
            case 2:
                return new FfiException.Session(
                    FfiConverterString.INSTANCE.Read(stream));
            case 3:
                return new FfiException.KeyChanged(
                    FfiConverterString.INSTANCE.Read(stream));
            case 4:
                return new FfiException.Internal(
                    FfiConverterString.INSTANCE.Read(stream));
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Read()", value));
        }
    }

    public override int AllocationSize(FfiException value) {
        switch (value) {

            case FfiException.Crypto variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case FfiException.Session variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case FfiException.KeyChanged variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);

            case FfiException.Internal variant_value:
                return 4
                    + FfiConverterString.INSTANCE.AllocationSize(variant_value.@msg);
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.AllocationSize()", value));
        }
    }

    public override void Write(FfiException value, BigEndianStream stream) {
        switch (value) {
            case FfiException.Crypto variant_value:
                stream.WriteInt(1);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case FfiException.Session variant_value:
                stream.WriteInt(2);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case FfiException.KeyChanged variant_value:
                stream.WriteInt(3);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            case FfiException.Internal variant_value:
                stream.WriteInt(4);
                FfiConverterString.INSTANCE.Write(variant_value.@msg, stream);
                break;
            default:
                throw new InternalException(String.Format("invalid error value '{0}' in FfiConverterTypeFfiError.Write()", value));
        }
    }
}




class FfiConverterOptionalUInt32: FfiConverterRustBuffer<uint?> {
    public static FfiConverterOptionalUInt32 INSTANCE = new FfiConverterOptionalUInt32();

    public override uint? Read(BigEndianStream stream) {
        if (stream.ReadByte() == 0) {
            return null;
        }
        return FfiConverterUInt32.INSTANCE.Read(stream);
    }

    public override int AllocationSize(uint? value) {
        if (value == null) {
            return 1;
        } else {
            return 1 + FfiConverterUInt32.INSTANCE.AllocationSize((uint)value);
        }
    }

    public override void Write(uint? value, BigEndianStream stream) {
        if (value == null) {
            stream.WriteByte(0);
        } else {
            stream.WriteByte(1);
            FfiConverterUInt32.INSTANCE.Write((uint)value, stream);
        }
    }
}




